create extension if not exists pgcrypto;
create table if not exists public.platform_market(id uuid primary key default gen_random_uuid(),platform_id uuid not null references public.platform(id) on delete cascade,market_code text not null,region_code text,product_available boolean not null default false,commercial_allowed boolean not null default false,status text not null default 'review' check(status in('review','approved','restricted')),evidence_url text,notes text,reviewed_at timestamptz,expires_at timestamptz,updated_at timestamptz not null default now(),unique(platform_id,market_code,region_code));
create table if not exists public.evidence_source(id uuid primary key default gen_random_uuid(),platform_id uuid references public.platform(id) on delete cascade,market_code text,source_type text not null default 'official',url text not null,title text,claim_scope text,observed_at timestamptz not null default now(),expires_at timestamptz,content_hash text,active boolean not null default true);
create table if not exists public.affiliate_click(id bigint generated by default as identity primary key,platform_id uuid references public.platform(id) on delete set null,market_code text,referrer text,user_agent text,created_at timestamptz not null default now());
create table if not exists public.content_revision(id bigint generated by default as identity primary key,entity_type text not null,entity_id text not null,change_type text not null,before_value jsonb,after_value jsonb,source text,created_at timestamptz not null default now());
create table if not exists public.monitor_run(id uuid primary key default gen_random_uuid(),status text not null default 'running',findings int not null default 0,started_at timestamptz not null default now(),finished_at timestamptz);
create table if not exists public.monitor_finding(id uuid primary key default gen_random_uuid(),run_id uuid references public.monitor_run(id) on delete cascade,platform_id uuid references public.platform(id) on delete cascade,severity text not null default 'info',code text not null,message text not null,resolved boolean not null default false,created_at timestamptz not null default now());
create table if not exists public.seo_platform_run(id uuid primary key default gen_random_uuid(),run_type text not null default 'daily',status text not null default 'running',gsc_rows int not null default 0,recommendations int not null default 0,warnings jsonb not null default '[]'::jsonb,started_at timestamptz not null default now(),finished_at timestamptz);
create table if not exists public.seo_platform_recommendation(id uuid primary key default gen_random_uuid(),recommendation_key text unique not null,page text not null,query text,type text not null,priority int not null default 50,status text not null default 'suggested',reason text,payload jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),applied_at timestamptz);
create table if not exists public.seo_platform_change(id bigint generated by default as identity primary key,recommendation_id uuid references public.seo_platform_recommendation(id),page text not null,change_type text not null,before_value jsonb,after_value jsonb,created_at timestamptz not null default now());
create table if not exists public.seo_job(id uuid primary key default gen_random_uuid(),type text not null,payload jsonb not null default '{}'::jsonb,result jsonb,priority int not null default 50,status text not null default 'queued',attempts int not null default 0,max_attempts int not null default 5,run_after timestamptz not null default now(),locked_at timestamptz,last_error text,created_at timestamptz not null default now(),finished_at timestamptz);
create index if not exists platform_market_lookup_idx on public.platform_market(platform_id,market_code,status);
create index if not exists monitor_finding_open_idx on public.monitor_finding(resolved,severity,created_at desc);
create index if not exists seo_platform_priority_idx on public.seo_platform_recommendation(status,priority desc);
create index if not exists seo_job_claim_idx on public.seo_job(status,run_after,priority desc);
alter table public.platform_market enable row level security;alter table public.evidence_source enable row level security;alter table public.affiliate_click enable row level security;alter table public.content_revision enable row level security;alter table public.monitor_run enable row level security;alter table public.monitor_finding enable row level security;alter table public.seo_platform_run enable row level security;alter table public.seo_platform_recommendation enable row level security;alter table public.seo_platform_change enable row level security;alter table public.seo_job enable row level security;
